    if (index == nums.length) {
        permutations.add(Arrays.asList(nums));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        int savedNum = nums[i];
        nums[i] = nums[index];
        nums[index] = savedNum;
        permute(nums, index + 1, permutations);
        nums[i] = savedNum;
        nums[index] = nums[i];
    }
}

