    // Set the ending n-tersection as the destination
    int[] destination = end;

    // Initialize a stack to keep track of n-tersections to visit
    Stack<int[]> toVisit = new Stack<>();

    // Add the starting n-tersection to the stack
    toVisit.add(start);

    // Loop until the stack is empty or the destination is found
    while (!toVisit.isEmpty()) {
        // Get the current n-tersection from the stack
        int[] current = toVisit.pop();

        // Check if the current n-tersection is the destination
        if (current[0] == destination[0] && current[1] == destination[1]) {
            // If the current n-tersection is the destination, return "can be travelled"
            return "can be travelled";
        }

        // Check if the current n-tersection has already been visited
        if (visited[current[0]][current[1]]) {
            // If the current n-tersection has already been visited, continue to the next n-tersection
            continue;
        }

        // Mark the current n-tersection as visited
        visited[current[0]][current[1]] = true;

        // Add the current n-tersection's neighbors to the stack
        for (int[] neighbor : getNeighbors(current, paths)) {
            toVisit.add(neighbor);
        }
    }

    // If the stack is empty and the destination has not been found, return "cannot be travelled"
    return "cannot be travelled";
}

private static List<int[]> getNeighbors(int[] nTersection, int[][] paths) {
    List<int[]> neighbors = new ArrayList<>();
    for (int[] path : paths) {
        if (path[0] == nTersection[0] && path[1] == nTersection[1]) {
            neighbors.add(path);
        }
    }
    return neighbors;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Convert the starting and ending coordinates to integer indices
  int startIndex = start[0] + n * start[1];
  int endIndex = end[0] + n * end[1];

  // Create a boolean array to mark visited n-tersections
  boolean[] visited = new boolean[n * n];
  Arrays.fill(visited, false);

  // Initialize a queue with the starting n-tersection
  Queue<Integer> queue = new LinkedList<Integer>();
  queue.add(startIndex);

  // Perform a Breadth-First Search from the starting n-tersection
  while (!queue.isEmpty()) {
    int current = queue.poll();
    visited[current] = true;
    for (int[] path : paths) {
      if (!visited[current + path[0] + n * path[1]]) {
        visited[current + path[0] + n * path[1]] = true;
        queue.add(current + path[0] + n * path[1]);
      }
    }
  }

  // Return "can be travelled" if the ending n-tersection is visited, otherwise "cannot be travelled"
  return visited[endIndex] ? "can be travelled" : "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a boolean array to keep track of visited n-tersections
  boolean[] visited = new boolean[n];
  // Set the starting n-tersection as visited
  visited[start[0] * n + start[1]] = true;

  // Loop through the paths and mark the connected n-tersections as visited
  for (int[] path : paths) {
    visited[path[0] * n + path[1]] = true;
  }

  // Check if the ending n-tersection has been visited
  if (visited[end[0] * n + end[1]]) {
    return "can be travelled";
  } else {
    return "cannot be travelled";
  }
}

