public double trimMean(int[] arr) {
    // Handle edge case: empty array
    if (arr.length == 0) {
        return 0;
    }

    // Calculate the mean of the array
    double mean = 0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

    // Remove the smallest 5% and largest 5% of the elements
    int low = (int) Math.floor(arr.length * 0.05);
    int high = arr.length - (int) Math.ceil(arr.length * 0.05);
    int count = 0;
    double sum = 0;
    for (int i = low; i < high; i++) {
        if (arr[i] > 0) {
            count++;
            sum += arr[i];
        }
    }

    // Calculate the trimmed mean
    double trimmedMean = sum / count;

    // Return the trimmed mean
    return trimmedMean;
}

public double trimMean(int[] arr) {
    // Calculate the mean of the remaining elements after removing the smallest 5% and largest 5% of the elements
    // Additional step 1: Calculate the mean of the entire array
    double mean = 0.0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

    // Additional step 2: Calculate the trimmed mean
    double trimmedMean = 0.0;
    int numTrimmed = (int) (0.05 * arr.length);
    for (int i = numTrimmed; i < arr.length - numTrimmed; i++) {
        trimmedMean += arr[i];
    }
    trimmedMean /= arr.length - 2 * numTrimmed;

    // Additional step 3: Handle edge cases
    if (numTrimmed == 0) {
        return mean;
    }
    if (numTrimmed == arr.length) {
        return 0.0;
    }
    return trimmedMean;
}

