public double trimMean(int[] arr) {
  // Calculate the mean of the input array
  double mean = 0.0;
  for (int i = 0; i < arr.length; i++) {
    mean += arr[i];
  }
  mean /= arr.length;

  // Calculate the threshold values for the smallest and largest 5% of the elements
  double thresholdSmall = mean / 20.0;
  double thresholdLarge = mean / 20.0 * 19.0;

  // Calculate the number of elements to ignore
  int numToIgnore = (int) Math.round(arr.length * 0.05);

  // Find the indices of the smallest and largest elements to ignore
  int smallestIndex = 0;
  int largestIndex = arr.length - 1;
  for (int i = 0; i < numToIgnore; i++) {
    if (arr[i] < arr[smallestIndex]) {
      smallestIndex = i;
    }
    if (arr[i] > arr[largestIndex]) {
      largestIndex = i;
    }
  }

  // Calculate the mean of the remaining elements
  double sum = 0.0;
  int count = 0;
  for (int i = 0; i < arr.length; i++) {
    if (arr[i] >= thresholdSmall && arr[i] <= thresholdLarge && i != smallestIndex && i != largestIndex) {
      sum += arr[i];
      count++;
    }
  }

  // Return the mean with an error within 10^-5
  return (double) Math.round(sum / (double) count * 1e5) / 1e5;
}

public boolean canArrange(int[] arr, int k) {
    // Check if the length of the array is divisible by 2 and if k is a positive integer
    if (arr.length % 2 != 0 || k <= 0) {
        return false;
    }

    // Initialize a count variable to keep track of the number of pairs
    int count = 0;

    // Iterate through the array and check if the sum of each pair is divisible by k
    for (int i = 0; i < arr.length - 1; i += 2) {
        int sum = arr[i] + arr[i + 1];
        if (sum % k == 0) {
            count++;
        }
    }

    // Check if the number of pairs is equal to n/2
    return count == arr.length / 2;
}

public boolean canArrange(int[] arr, int k) {
    // Step 1: Sort the array in increasing order
    Arrays.sort(arr);

    // Step 2: Divide the array into n/2 pairs
    int n = arr.length;
    int midIndex = n / 2;
    int[][] pairs = new int[midIndex][2];
    for (int i = 0; i < midIndex; i++) {
        pairs[i][0] = arr[i];
        pairs[i][1] = arr[n - i - 1];
    }

    // Step 3: Check if the sum of each pair is divisible by k
    for (int i = 0; i < midIndex; i++) {
        if ((pairs[i][0] + pairs[i][1]) % k != 0) {
            return false;
        }
    }

    return true;
}

public static boolean canArrange(int[] arr, int k) {
        if (arr.length % 2 != 0) {
            return false;
        }

        Map<Integer, Integer> countMap = getCountMap(arr);
        int count = 0;
        for (int i = 0; i < arr.length / 2; i++) {
            int currentSum = countMap.getOrDefault(i, 0) + countMap.getOrDefault(i + arr.length / 2, 0);
            if (currentSum % k != 0) {
                count++;
            }
        }

        return count == 0;
    }

private static Map<Integer, Integer> getCountMap(int[] arr) {
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            int count = 0;
            for (int j = 0; j < arr.length; j++) {
                if (i != j && arr[i] + arr[j] % 2 == 0) {
                    count++;
                }
            }
            countMap.put(i, count);
        }
        return countMap;
    }

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }

    for (int i = 0; i < arr.length - 1; i += 2) {
        int sum = arr[i] + arr[i + 1];
        if (sum % k != 0) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
  // Handle edge case where the array is empty or has only one element
  if (arr.length < 2) {
    return false;
  }

  // Check if the array can be divided into n/2 pairs
  int n = arr.length / 2;
  if (n * 2 != arr.length) {
    return false;
  }

  // Check if each pair in the array has a sum that is divisible by k
  for (int i = 0; i < n; i++) {
    int sum = arr[i * 2] + arr[i * 2 + 1];
    if (sum % k != 0) {
      return false;
    }
  }

  // All checks passed, return true
  return true;
}

