    // Create a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a variable to store the minimum time
    int minTime = 0;

    // Traverse the graph starting from node 0
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime += graph.getMinDistance(0, i);
        }
    }

    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Check if the input is valid
    if (n <= 0 || edges == null || hasApple == null || edges.length != n || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Create a graph representation of the tree
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int i = 0; i < edges.length; i++) {
        graph.get(edges[i][0]).add(edges[i][1]);
        graph.get(edges[i][1]).add(edges[i][0]);
    }

    // Initialize the minimum time required to collect all the apples and return to node 0
    int minTime = 0;

    // Traverse the graph starting from node 0
    List<Integer> queue = new ArrayList<>();
    queue.add(0);
    while (!queue.isEmpty()) {
        int currentNode = queue.remove(0);

        // Check if the current node has an apple
        if (hasApple[currentNode]) {
            // Update the minimum time required to collect the apple
            minTime = Math.max(minTime, graph.get(currentNode).size());
        }

        // Add the neighboring nodes of the current node to the queue
        for (int neighbor : graph.get(currentNode)) {
            if (!queue.contains(neighbor)) {
                queue.add(neighbor);
            }
        }
    }

    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0 || edges.length == 0 || hasApple.length == 0) {
        return 0;
    }

    int minTime = Integer.MAX_VALUE;
    int[] visited = new int[n];

    // DFS to find the minimum time
    dfs(0, visited, edges, hasApple, 0, 0, minTime);

    // Return the minimum time
    return minTime;
}

private void dfs(int currentNode, int[] visited, int[][] edges, boolean[] hasApple, int timeSoFar, int parentNode, int minTime) {
    visited[currentNode] = 1;
    timeSoFar += 1;

    if (hasApple[currentNode]) {
        timeSoFar += 1;
    }

    for (int i = 0; i < edges[currentNode].length; i++) {
        int node = edges[currentNode][i];

        if (node != parentNode && visited[node] == 0) {
            dfs(node, visited, edges, hasApple, timeSoFar, currentNode, minTime);
        }
    }

    if (timeSoFar < minTime) {
        minTime = timeSoFar;
    }
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Edge case: If there are no apples, return 0
  if (hasApple.length == 0) {
    return 0;
  }

  // Create a graph with n nodes and edges
  Graph graph = new Graph(n, edges);

  // Initialize the minimum time to 0
  int minTime = 0;

  // Iterate over all nodes
  for (int i = 0; i < n; i++) {
    // If the current node has an apple
    if (hasApple[i]) {
      // Update the minimum time
      minTime = Math.min(minTime, graph.getShortestPathLength(0, i));
    }
  }

  // Return the minimum time
  return minTime;
}

public Graph(int numNodes, int[][] edges) {
    this.numNodes = numNodes;
    this.edges = new ArrayList<List<Integer>>();

    // Add the edges to the graph
    for (int i = 0; i < edges.length; i++) {
      int from = edges[i][0];
      int to = edges[i][1];
      List<Integer> edge = new ArrayList<Integer>();
      edge.add(from);
      edge.add(to);
      edges.add(edge);
    }
  }

public int getShortestPathLength(int node1, int node2) {
    // Initialize the shortest path length to 0
    int shortestPathLength = 0;

    // Create a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<Integer>();

    // Add the starting node to the queue
    queue.offer(node1);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
      // Get the next node from the queue
      int currentNode = queue.poll();

      // If the current node is the destination node, return the shortest path length
      if (currentNode == node2) {
        return shortestPathLength;
      }

      // Loop over the neighbors of the current node
      for (int neighbor : edges.get(currentNode)) {
        // If the neighbor has not been visited yet, add it to the queue
        if (!queue.contains(neighbor)) {
          queue.offer(neighbor);
        }
      }

      // Increment the shortest path length
      shortestPathLength++;
    }

    // Return the shortest path length
    return shortestPathLength;
  }

public String sortString(String s) {
  if (s == null || s.isEmpty()) {
    return s;
  }

  char[] chars = s.toCharArray();
  Arrays.sort(chars);

  StringBuilder result = new StringBuilder();
  result.append(chars[0]);

  for (int i = 1; i < chars.length - 1; i++) {
    char current = chars[i];
    char next = chars[i + 1];
    if (current > next) {
      result.append(current);
      result.append(next);
    } else {
      result.append(next);
      result.append(current);
    }
  }

  if (chars.length % 2 == 0) {
    result.append(chars[chars.length - 1]);
  }

  return result.toString();
}

public String sortString(String s) {
    // Step 1: Sort the string in ascending order
    char[] sortedChars = s.toCharArray();
    Arrays.sort(sortedChars);

    // Step 2: Append the smallest character to the result string
    StringBuilder result = new StringBuilder(sortedChars[0]);

    // Step 3: Append the next smallest character to the result string
    // If the smallest character appears more than once, choose the first occurrence
    int currentIndex = 1;
    while (currentIndex < sortedChars.length) {
        if (sortedChars[currentIndex] > result.charAt(result.length() - 1)) {
            result.append(sortedChars[currentIndex]);
            currentIndex++;
        } else {
            break;
        }
    }

    // Step 4: Append the largest character to the result string
    result.append(sortedChars[sortedChars.length - 1]);

    // Step 5: Append the second largest character to the result string
    // If the second largest character appears more than once, choose the first occurrence
    int secondLargestIndex = sortedChars.length - 2;
    while (secondLargestIndex >= 0) {
        if (sortedChars[secondLargestIndex] < result.charAt(result.length() - 1)) {
            result.append(sortedChars[secondLargestIndex]);
            secondLargestIndex--;
        } else {
            break;
        }
    }

    // Step 6: Repeat steps 1-5 until all characters in the input string have been used
    while (currentIndex < sortedChars.length) {
        result = new StringBuilder(sortedChars[currentIndex]);
        currentIndex++;
        while (currentIndex < sortedChars.length) {
            if (sortedChars[currentIndex] > result.charAt(result.length() - 1)) {
                result.append(sortedChars[currentIndex]);
                currentIndex++;
            } else {
                break;
            }
        }
        result.append(sortedChars[sortedChars.length - 1]);
        secondLargestIndex = sortedChars.length - 2;
        while (secondLargestIndex >= 0) {
            if (sortedChars[secondLargestIndex] < result.charAt(result.length() - 1)) {
                result.append(sortedChars[secondLargestIndex]);
                secondLargestIndex--;
            } else {
                break;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    StringBuilder result = new StringBuilder();
    char[] charArray = s.toCharArray();
    Arrays.sort(charArray);
    int pickingIndex = 0;
    while (pickingIndex < charArray.length) {
        char picked = charArray[pickingIndex];
        result.append(picked);
        pickingIndex = getNextIndex(charArray, picked, pickingIndex);
    }
    return result.toString();
}

private int getNextIndex(char[] charArray, char picked, int currentIndex) {
    int nextIndex = currentIndex + 1;
    while (nextIndex < charArray.length && charArray[nextIndex] == picked) {
        nextIndex++;
    }
    return nextIndex;
}

public String sortString(String s) {
    // Step 1: Sort the input string
    char[] chars = s.toCharArray();
    Arrays.sort(chars);

    // Step 2: Create a new string with the sorted characters
    String result = "";
    for (int i = 0; i < chars.length; i++) {
        result += chars[i];
    }

    // Step 3: Reverse the order of the characters
    result = new StringBuilder(result).reverse().toString();

    return result;
}

public String sortString(String s) {
    // Edge case: empty string
    if (s.isEmpty()) {
        return "";
    }

    // Sort the characters in the string
    char[] sortedChars = s.toCharArray();
    Arrays.sort(sortedChars);

    // Create a new string with the sorted characters
    StringBuilder sb = new StringBuilder();
    for (char c : sortedChars) {
        sb.append(c);
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length < 2) {
        return false;
    }
    double average = getAverage(nums);
    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
        sum += nums[i];
    }
    int leftSum = 0;
    int rightSum = sum;
    for (int i = 0; i < nums.length; i++) {
        if (leftSum == rightSum) {
            return true;
        }
        leftSum += nums[i];
        rightSum -= nums[i];
    }
    return false;
}

private double getAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    return (double) sum / nums.length;
}

