    for (int num : nums) {
        sum += num;
    }
    float average = (float) sum / nums.length;

    for (int i = 0; i < nums.length - 1; i++) {
        int currentSum = 0;
        for (int j = i + 1; j < nums.length; j++) {
            currentSum += nums[j];
            if (currentSum == average * (j - i)) {
                return true;
            }
        }
    }

