}

public boolean splitArraySameAverage(int[] nums) {
  // Calculate the average of the input array
  double average = Arrays.stream(nums).average().orElse(0.0);

  // Initialize variables for the left and right arrays
  double leftSum = 0;
  double rightSum = 0;

  // Loop through the input array and try to split it into two arrays with the same average
  for (int i = 0; i < nums.length; i++) {
    if (leftSum + nums[i] <= average && rightSum + nums[i] <= average) {
      leftSum += nums[i];
    } else if (rightSum + nums[i] >= average && leftSum + nums[i] >= average) {
      rightSum += nums[i];
    } else {
      return false;
    }
  }

  // Check if the left and right arrays have the same average
  return Math.abs(leftSum - rightSum) < 1e-6;
}

public int minCostClimbingStairs(int[] cost) {
  int minCost = Integer.MAX_VALUE;
  int currentCost = 0;
  for (int i = 0; i < cost.length; i++) {
    currentCost += cost[i];
    if (i == cost.length - 1 || i == cost.length - 2) {
      minCost = Math.min(minCost, currentCost);
      currentCost = 0;
    }
  }
  return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return 1;
    }
    int minCost = 0;
    int currentCost = 1;
    for (int i = 1; i < cost.length; i++) {
        currentCost = Math.min(currentCost, cost[i - 1]);
        minCost += currentCost;
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    for (int i = 0; i < cost.length; i++) {
        if (cost[i] < minCost) {
            minCost = cost[i];
        }
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    for (int i = 0; i < cost.length; i++) {
        if (i == 0 || i == 1) {
            int currentCost = cost[i];
            int nextCost = i + 1 < cost.length ? cost[i + 1] : 0;
            minCost = Math.min(minCost, currentCost + nextCost);
            for (int j = 0; j < 2; j++) {
                int previousCost = i - 1 >= 0 ? cost[i - 1] : 0;
                minCost = Math.min(minCost, previousCost + currentCost + nextCost);
            }
        }
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

