for (String word : words) {
StringBuilder morseCode = new StringBuilder();
for (char ch : word.toCharArray()) {
morseCode.append(getMorseCode(ch));
}

if (!transformations.containsKey(morseCode.toString())) {
transformations.put(morseCode.toString(), 1);
