public boolean hasAllCodes(String s, int k) {
	if (s.length() < k) {
		return false;
	}
	for (int i = 0; i <= s.length() - k; i++) {
		if (!s.substring(i, i + k).equals((new StringBuilder(k)).toString())) {
			return false;
		}
	}
	return true;
}

public boolean hasAllCodes(String s, int k) {
    // Initialize a set to store all binary strings of length k
    Set<String> codes = new HashSet<>();

    // Iterate over the string s
    for (int i = 0; i <= s.length() - k; i++) {
        // Get the binary string of length k starting at index i
        String code = s.substring(i, i + k);

        // Add the binary string to the set
        codes.add(code);
    }

    // Return true if the set contains all binary strings of length k, or false otherwise
    return codes.size() == (int)Math.pow(2, k);
}

public boolean hasAllCodes(String s, int k) {
    // Step 1: Initialize a set to store the substrings of length k
    Set<String> substrings = new HashSet<>();

    // Step 2: Iterate over the characters of the input string
    for (int i = 0; i < s.length() - k + 1; i++) {
        // Step 3: Consider each substring of length k starting from the current index
        String substring = s.substring(i, i + k);

        // Step 4: If the substring is not already in the set, add it and check if it's a valid binary string
        if (!substrings.contains(substring) && isValidBinaryString(substring)) {
            substrings.add(substring);
        }
    }

    // Step 5: Return true if every binary string of length k is a substring of s, or false otherwise
    return substrings.size() == Math.pow(2, k);
}

private static boolean isValidBinaryString(String s) {
    return s.matches("[01]+");
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < k) {
        return false;
    }
    for (int i = 0; i <= s.length() - k; i++) {
        String substr = s.substring(i, i + k);
        if (!substr.endsWith(Character.toString(s.charAt(i)))) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
  // Edge case: If the length of s is less than k, return false
  if (s.length() < k) {
    return false;
  }

  // Initialize a set to store the binary strings of length k
  Set<String> binaryStrings = new HashSet<>();

  // Loop through the string s and add each binary string of length k to the set
  for (int i = 0; i <= s.length() - k; i++) {
    binaryStrings.add(s.substring(i, i + k));
  }

  // If the set contains all possible binary strings of length k, return true
  if (binaryStrings.size() == (int) Math.pow(2, k)) {
    return true;
  }

  // Otherwise, return false
  return false;
}

