private List<Integer> getFactors(int n) {
    List<Integer> factors = new ArrayList<>();
    factors.add(1);
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 2; i <= sqrtN; i++) {
        if (n % i == 0) {
            factors.add(i);
            factors.add(n / i);
        }
    }
    return factors;
}

