public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    char[] chars = s.toCharArray();
    boolean[] isGood = new boolean[chars.length];
    int n = chars.length;
    int start = 0;
    int end = 0;
    boolean found = false;

    for (int i = 0; i < n; i++) {
        if ((Character.isLowerCase(chars[i]) && Character.isUpperCase(chars[i - 1]))
                || (Character.isUpperCase(chars[i]) && Character.isLowerCase(chars[i - 1]))) {
            found = true;
            isGood[i] = false;
            isGood[i - 1] = false;
        }
    }

    if (found) {
        for (int i = 0; i < n; i++) {
            if (isGood[i]) {
                start = i;
                break;
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            if (isGood[i]) {
                end = i;
                break;
            }
        }
        return new String(chars, 0, start) + new String(chars, end, n - end);
    } else {
        return s;
    }
}

