    Set<Integer> visitedChars = new HashSet<>();

    // Loop through the characters in the string
    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);

        // Check if the current character is lowercase
        if (Character.isLowerCase(currentChar)) {
            // Check if the corresponding uppercase character has been visited
            if (visitedChars.contains(Character.toUpperCase(currentChar))) {
                // Remove the current character and the corresponding uppercase character
                s = s.substring(0, i) + s.substring(i + 1);
