    }

    // Step 5: Apply the moving logic
    int result = 0;
    for (int i : movableIndices) {
        int[] newArr = new int[A.length];
        for (int j = 0; j < A.length; j++) {
            if (j == i) {
                newArr[j] = A[j < i ? i : 0];
            } else {
                newArr[j] = A[j];
            }
        }
        result += countSquarePermutations(newArr);
    }

