    if (heights == null || heights.length == 0) {
        return 0;
    }

    // find the maximum height in the array
    int maxHeight = heights[0];
    for (int i = 1; i < heights.length; i++) {
        if (heights[i] > maxHeight) {
            maxHeight = heights[i];
        }
    }

    // find the indices of the elements in the array that have the maximum height
    List<Integer> maxHeightIndices = new ArrayList<>();
    for (int i = 0; i < heights.length; i++) {
        if (heights[i] == maxHeight) {
            maxHeightIndices.add(i);
        }
    }

    // find the indices of the elements in the array that have the maximum height and are consecutive
    List<Integer> consecutiveMaxHeightIndices = new ArrayList<>();
    for (int i = 0; i < maxHeightIndices.size() - 1; i++) {
        if (maxHeightIndices.get(i) + 1 == maxHeightIndices.get(i + 1)) {
            consecutiveMaxHeightIndices.add(maxHeightIndices.get(i));
        }
    }

    // find the largest rectangle area
    int largestRectangleArea = 0;
    for (int i = 0; i < consecutiveMaxHeightIndices.size() - 1; i++) {
        int currentArea = (consecutiveMaxHeightIndices.get(i) + 1) * maxHeight;
        if (currentArea > largestRectangleArea) {
            largestRectangleArea = currentArea;
        }
    }

    return largestRectangleArea;
}

