    if (n < 0) {
        return -1;
    }

    int smallest = -1;
    int[] digits = getDigits(n);
    do {
        int current = getNumber(digits);
        if (current > n && (smallest == -1 || current < smallest)) {
            smallest = current;
        }
    } while (nextPermutation(digits));

    return smallest;
}

private static int[] getDigits(int n) {
    List<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }
    return digits.stream().mapToInt(i -> i).toArray();
}

private static int getNumber(int[] digits) {
    int number = 0;
    for (int i = 0; i < digits.length; i++) {
        number = number * 10 + digits[i];
    }
    return number;
}

private static boolean nextPermutation(int[] digits) {
    // Find the first digit that is not in its final position
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit exists, this is the last permutation
    if (i == -1) {
        return false;
    }

    // Find the first digit that is greater than the digit at position i
    int j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap the digit at position i with the digit at position j
    int temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits from position i + 1 to the end
    j = digits.length - 1;
    while (i < j) {
        temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;
        i++;
        j--;
    }

    return true;
}

