    if (digits.substring(i, i + 1).equals("0")) {
      continue;
    }
    String smallest = digits.substring(i + 1);
    for (int j = 0; j < digits.length() - i - 1; j++) {
      String current = smallest.concat(digits.substring(i, i + 1));
      if (Integer.parseInt(current) > Integer.parseInt(smallest)) {
        smallest = current;
        break;
      }
    }
    if (Integer.parseInt(smallest) > n) {
      return Integer.parseInt(smallest);
    }
  }
  return -1;
}

