public static int findNthUglyNumber(int n) {
    /**
     * This method implements a solution to the "Ugly Number" problem.
     * The problem statement is as follows:
     * Find and return the nth ugly number.
     *
     * An ugly number is a positive integer that is divisible by 2, 3, or 5.
     *
     * @param n The index of the ugly number to find.
     * @return The nth ugly number.
     *
     * Example:
     * findNthUglyNumber(10)
     * Output: 12
     */
    // Step 1: Define the set of ugly numbers
    Set<Integer> uglyNumbers = new HashSet<>();
    // Step 2: Define the set of multiples of 2, 3, and 5
    Set<Integer> multiplesOf2 = new HashSet<>();
    Set<Integer> multiplesOf3 = new HashSet<>();
    Set<Integer> multiplesOf5 = new HashSet<>();
    // Step 3: Initialize the sets with the first ugly number
    uglyNumbers.add(1);
    multiplesOf2.add(2);
    multiplesOf3.add(3);
    multiplesOf5.add(5);
    // Step 4: Iterate through the desired number of loops
    for (int i = 1; i < n; i++) {
        // Step 5: Add the next set of multiples to the set of ugly numbers
        uglyNumbers.addAll(multiplesOf2);
        uglyNumbers.addAll(multiplesOf3);
        uglyNumbers.addAll(multiplesOf5);
        // Step 6: Update the multiples sets
        multiplesOf2.add(2 * uglyNumbers.size());
        multiplesOf3.add(3 * uglyNumbers.size());
        multiplesOf5.add(5 * uglyNumbers.size());
    }
    // Step 7: Return the nth ugly number
    return uglyNumbers.size();
}

