    uglyNumbers[0] = 1;
    for (int i = 1; i < n; i++) {
        uglyNumbers[i] = min(uglyNumbers[i - 1] * 2, uglyNumbers[i - 1] * 3, uglyNumbers[i - 1] * 5);
