public static int minPerfectSquareSum(int n) {
    int[] squares = new int[n+1];
    squares[0] = 0;
    int sum = 0;

    for (int i = 1; i <= n; i++) {
        sum += i*i;
        if (sum > n) {
            return i - 1;
        }
        squares[i] = sum;
    }

    return squares.length;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        if (root * root == n) {
            count++;
            break;
        }
        n -= root;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    // Step 1: Check if the input is valid
    if (n <= 0) {
        throw new IllegalArgumentException("Invalid input: n must be a positive integer");
    }

    // Step 2: Initialize the minimum number of perfect squares
    int minNumSquares = Integer.MAX_VALUE;

    // Step 3: Loop through all possible perfect squares
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int square = i * i;

        // Step 4: Check if the square is less than or equal to the target
        if (square <= n) {
            // Step 5: Count the number of perfect squares needed to sum up to n
            int numSquares = 0;
            while (square <= n) {
                numSquares++;
                square += i * i;
            }

            // Step 6: Update the minimum number of perfect squares if necessary
            if (numSquares < minNumSquares) {
                minNumSquares = numSquares;
            }
        }
    }

    return minNumSquares;
}

public static int minPerfectSquareSum(int n) {
    // Edge case: If the input is less than or equal to 0, return 0
    if (n <= 0) {
        return 0;
    }

    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Loop through the range of values from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        // If the current value is a perfect square, add it to the list
        if (i * i == n) {
            perfectSquares.add(i);
        }
    }

    // Return the size of the list
    return perfectSquares.size();
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        if (root * root == n) {
            minSquares++;
            n = 0;
        } else {
            int difference = n - (root + 1) * (root + 1);
            if (difference < 0) {
                root--;
                difference = n - (root + 1) * (root + 1);
            }
            minSquares++;
            n = difference;
        }
    }
    return minSquares;
}

public static String reverseWords(String s) {
    return Arrays.stream(s.split(" "))
            .map(word -> new StringBuilder(word).reverse().toString())
            .collect(Collectors.joining(" "));
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        char[] wordChars = words[i].toCharArray();
        int left = 0;
        int right = wordChars.length - 1;
        while (left < right) {
            char temp = wordChars[left];
            wordChars[left] = wordChars[right];
            wordChars[right] = temp;
            left++;
            right--;
        }
        words[i] = new String(wordChars);
    }
    return String.join(" ", words);
}

